-- ============================================================
-- 创新创业项目管理系统 - 数据库初始化脚本
-- 数据库: MySQL 8.0
-- 字符集: utf8mb4
-- ============================================================

CREATE DATABASE IF NOT EXISTS ie_project_db DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE ie_project_db;

-- 禁用外键检查以便重建表
SET FOREIGN_KEY_CHECKS = 0;

DROP TABLE IF EXISTS `sys_college`;
DROP TABLE IF EXISTS `sys_user`;
DROP TABLE IF EXISTS `sys_dict`;
DROP TABLE IF EXISTS `biz_competition`;
DROP TABLE IF EXISTS `biz_announcement`;
DROP TABLE IF EXISTS `proj_project`;
DROP TABLE IF EXISTS `proj_team_member`;
DROP TABLE IF EXISTS `proj_review`;
DROP TABLE IF EXISTS `proj_budget`;
DROP TABLE IF EXISTS `proj_expense`;
DROP TABLE IF EXISTS `proj_achievement`;
DROP TABLE IF EXISTS `proj_midterm_check`;
DROP TABLE IF EXISTS `proj_change_request`;
DROP TABLE IF EXISTS `sys_attachment`;
DROP TABLE IF EXISTS `sys_operation_log`;

-- sys_college
CREATE TABLE `sys_college` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '学院ID',
  `college_code` varchar(32) NOT NULL COMMENT '学院编码',
  `college_name` varchar(128) NOT NULL COMMENT '学院名称',
  `dean_id` bigint DEFAULT NULL COMMENT '院长用户ID',
  `sort_order` int NOT NULL DEFAULT '0' COMMENT '排序',
  `status` tinyint NOT NULL DEFAULT '1' COMMENT '状态: 0-停用 1-启用',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `is_deleted` tinyint NOT NULL DEFAULT '0' COMMENT '软删除标记',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_college_code` (`college_code`),
  UNIQUE KEY `uk_college_name` (`college_name`),
  KEY `fk_college_dean` (`dean_id`),
  CONSTRAINT `fk_college_dean` FOREIGN KEY (`dean_id`) REFERENCES `sys_user` (`id`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=1 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='学院表';

-- sys_user
CREATE TABLE `sys_user` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '用户ID',
  `username` varchar(64) NOT NULL COMMENT '登录账号(学号/工号)',
  `password_hash` varchar(255) NOT NULL COMMENT '密码哈希',
  `real_name` varchar(64) NOT NULL COMMENT '真实姓名',
  `email` varchar(128) DEFAULT NULL COMMENT '邮箱',
  `phone` varchar(20) DEFAULT NULL COMMENT '手机号',
  `role` tinyint NOT NULL DEFAULT '1' COMMENT '角色: 1-学生 2-指导教师 3-评审专家 4-系统管理员',
  `college_id` bigint DEFAULT NULL COMMENT '所属学院ID',
  `grade` varchar(32) DEFAULT NULL COMMENT '年级',
  `gender` varchar(10) DEFAULT NULL COMMENT '性别',
  `major` varchar(100) DEFAULT NULL COMMENT '专业(学生)',
  `title` varchar(64) DEFAULT NULL COMMENT '职称(教师/专家)',
  `direction` varchar(255) DEFAULT NULL COMMENT '研究方向(教师/专家)',
  `organization` varchar(255) DEFAULT NULL COMMENT '所属单位(专家)',
  `avatar` longtext,
  `status` tinyint NOT NULL DEFAULT '1' COMMENT '状态: 0-禁用 1-启用',
  `force_change_pwd` tinyint NOT NULL DEFAULT '0' COMMENT '首次登录强制改密',
  `last_login_at` datetime DEFAULT NULL COMMENT '最后登录时间',
  `last_login_ip` varchar(64) DEFAULT NULL COMMENT '最后登录IP',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `is_deleted` tinyint NOT NULL DEFAULT '0' COMMENT '软删除标记: 0-未删除 1-已删除',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_username` (`username`),
  KEY `idx_college` (`college_id`),
  KEY `idx_role` (`role`),
  KEY `idx_status` (`status`),
  KEY `idx_email` (`email`),
  KEY `idx_phone` (`phone`),
  CONSTRAINT `fk_user_college` FOREIGN KEY (`college_id`) REFERENCES `sys_college` (`id`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=1 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='系统用户表';

-- sys_dict
CREATE TABLE `sys_dict` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '字典ID',
  `dict_type` varchar(64) NOT NULL COMMENT '字典类型',
  `dict_code` varchar(64) NOT NULL COMMENT '字典编码',
  `dict_label` varchar(255) NOT NULL COMMENT '字典标签',
  `dict_value` varchar(255) DEFAULT NULL COMMENT '字典值',
  `sort_order` int NOT NULL DEFAULT '0' COMMENT '排序',
  `status` tinyint NOT NULL DEFAULT '1' COMMENT '状态: 0-禁用 1-启用',
  `remark` varchar(500) DEFAULT NULL COMMENT '备注',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_type_code` (`dict_type`,`dict_code`),
  KEY `idx_type` (`dict_type`)
) ENGINE=InnoDB AUTO_INCREMENT=1 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='系统字典表';

-- biz_competition
CREATE TABLE `biz_competition` (
  `title` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '比赛名称',
  `session` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '届次(如 2026届)',
  `competition_type` smallint NOT NULL COMMENT '比赛类型',
  `level` smallint NOT NULL COMMENT '比赛级别',
  `organizer` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '主办方',
  `co_organizer` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '承办方',
  `description` text COLLATE utf8mb4_unicode_ci COMMENT '比赛简介',
  `requirements` text COLLATE utf8mb4_unicode_ci COMMENT '参赛要求',
  `rewards` text COLLATE utf8mb4_unicode_ci COMMENT '奖项设置',
  `registration_start` date DEFAULT NULL COMMENT '报名开始日期',
  `registration_end` date DEFAULT NULL COMMENT '报名截止日期',
  `competition_start` date DEFAULT NULL COMMENT '比赛开始日期',
  `competition_end` date DEFAULT NULL COMMENT '比赛结束日期',
  `college_review_date` date DEFAULT NULL COMMENT '学院初审审核日(兼指导教师确认截止日)',
  `university_review_date` date DEFAULT NULL COMMENT '校级复审审核日',
  `expert_review_date` date DEFAULT NULL COMMENT '专家评审审核日',
  `midterm_deadline` date DEFAULT NULL COMMENT '中期报告提交截止日',
  `final_deadline` date DEFAULT NULL COMMENT '结题报告提交截止日',
  `location` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '比赛地点',
  `contact` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '联系方式',
  `cover_image` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '封面图URL',
  `official_url` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '官方链接',
  `status` smallint NOT NULL COMMENT '比赛状态',
  `view_count` bigint NOT NULL COMMENT '浏览次数',
  `created_by` bigint DEFAULT NULL COMMENT '创建人ID',
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '更新时间',
  `is_deleted` smallint NOT NULL COMMENT '软删除标记: 0-未删除 1-已删除',
  PRIMARY KEY (`id`),
  KEY `created_by` (`created_by`),
  KEY `idx_competition_status` (`status`),
  KEY `idx_competition_level` (`level`),
  KEY `idx_competition_type` (`competition_type`),
  CONSTRAINT `biz_competition_ibfk_1` FOREIGN KEY (`created_by`) REFERENCES `sys_user` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=1 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- biz_announcement
CREATE TABLE `biz_announcement` (
  `title` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '公告标题',
  `content` text COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '公告内容',
  `announcement_type` smallint NOT NULL COMMENT '公告类型',
  `status` smallint NOT NULL COMMENT '发布状态',
  `priority` smallint NOT NULL COMMENT '优先级',
  `publish_time` datetime DEFAULT NULL COMMENT '发布时间',
  `expire_time` datetime DEFAULT NULL COMMENT 'expire time auto offline',
  `view_count` bigint NOT NULL COMMENT '浏览次数',
  `created_by` bigint DEFAULT NULL COMMENT '创建人ID',
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '更新时间',
  `is_deleted` smallint NOT NULL COMMENT '软删除标记: 0-未删除 1-已删除',
  PRIMARY KEY (`id`),
  KEY `created_by` (`created_by`),
  KEY `idx_announcement_status` (`status`),
  KEY `idx_announcement_type` (`announcement_type`),
  KEY `idx_announcement_priority` (`priority`),
  CONSTRAINT `biz_announcement_ibfk_1` FOREIGN KEY (`created_by`) REFERENCES `sys_user` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=1 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- proj_project
CREATE TABLE `proj_project` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '项目ID',
  `project_no` varchar(64) DEFAULT NULL COMMENT '项目编号',
  `project_name` varchar(255) NOT NULL COMMENT '项目名称',
  `project_type` tinyint NOT NULL DEFAULT '1' COMMENT '项目类型: 1-创新训练 2-创业训练 3-创业实践',
  `project_level` tinyint NOT NULL DEFAULT '1' COMMENT '项目级别: 1-院级 2-校级 3-省级 4-国家级',
  `college_id` bigint NOT NULL COMMENT '申报学院ID',
  `leader_id` bigint NOT NULL COMMENT '项目负责人(学生)ID',
  `teacher_id` bigint DEFAULT NULL COMMENT '指导教师ID',
  `competition_id` bigint DEFAULT NULL COMMENT '参赛比赛ID',
  `competition_session` varchar(32) DEFAULT NULL COMMENT '参赛比赛届次(冗余,如 2026届)',
  `start_date` date DEFAULT NULL COMMENT '立项开始日期',
  `end_date` date DEFAULT NULL COMMENT '计划结束日期',
  `budget_amount` decimal(12,2) NOT NULL DEFAULT '0.00' COMMENT '预算总额(元)',
  `used_amount` decimal(12,2) NOT NULL DEFAULT '0.00' COMMENT '已使用金额(元)',
  `project_summary` text COMMENT '项目简介',
  `innovation_points` text COMMENT '创新点',
  `expected_results` text COMMENT '预期成果',
  `status` tinyint NOT NULL DEFAULT '0' COMMENT '项目状态: 0-草稿 1-待学院初审 2-学院初审通过 3-待校级复审 4-校级复审通过 13-待分配评审专家 5-待专家评审 6-已立项 7-中期检查 8-待结题 9-已结题 10-已驳回 11-已撤销',
  `submit_time` datetime DEFAULT NULL COMMENT '正式提交时间',
  `approval_time` datetime DEFAULT NULL COMMENT '最终立项审批时间',
  `current_approver_id` bigint DEFAULT NULL COMMENT '当前审批人ID',
  `reject_reason` varchar(500) DEFAULT NULL COMMENT '驳回原因',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `is_deleted` tinyint NOT NULL DEFAULT '0' COMMENT '软删除标记',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_project_no` (`project_no`),
  KEY `idx_college` (`college_id`),
  KEY `idx_leader` (`leader_id`),
  KEY `idx_teacher` (`teacher_id`),
  KEY `idx_status` (`status`),
  KEY `idx_type_level` (`project_type`,`project_level`),
  KEY `idx_competition` (`competition_id`),
  CONSTRAINT `fk_project_college` FOREIGN KEY (`college_id`) REFERENCES `sys_college` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `fk_project_leader` FOREIGN KEY (`leader_id`) REFERENCES `sys_user` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `fk_project_teacher` FOREIGN KEY (`teacher_id`) REFERENCES `sys_user` (`id`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=1 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='创新创业项目表';

-- proj_team_member
CREATE TABLE `proj_team_member` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '记录ID',
  `project_id` bigint NOT NULL COMMENT '项目ID',
  `student_id` bigint NOT NULL COMMENT '学生用户ID',
  `student_name` varchar(64) NOT NULL COMMENT '学生姓名(冗余)',
  `student_no` varchar(64) NOT NULL COMMENT '学号(冗余)',
  `major` varchar(128) DEFAULT NULL COMMENT '专业',
  `grade` varchar(32) DEFAULT NULL COMMENT '年级',
  `role_in_team` varchar(64) DEFAULT NULL COMMENT '团队内角色',
  `task_desc` varchar(255) DEFAULT NULL COMMENT '分工描述',
  `join_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '加入时间',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `is_deleted` tinyint NOT NULL DEFAULT '0' COMMENT '软删除标记',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_project_student` (`project_id`,`student_id`),
  KEY `idx_student` (`student_id`),
  CONSTRAINT `fk_team_project` FOREIGN KEY (`project_id`) REFERENCES `proj_project` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `fk_team_student` FOREIGN KEY (`student_id`) REFERENCES `sys_user` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=1 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='项目团队成员表';

-- proj_review
CREATE TABLE `proj_review` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '记录ID',
  `project_id` bigint NOT NULL COMMENT '项目ID',
  `review_stage` tinyint NOT NULL COMMENT '审核阶段: 1-学院初审 2-校级复审 3-专家评审 4-结题验收',
  `reviewer_id` bigint NOT NULL COMMENT '审核人ID',
  `reviewer_name` varchar(64) NOT NULL COMMENT '审核人姓名(冗余)',
  `review_result` tinyint NOT NULL COMMENT '审核结果: 1-通过 2-驳回 3-修改后重提',
  `score` decimal(5,2) DEFAULT NULL COMMENT '评分(百分制,专家评审用)',
  `dim_scores` json DEFAULT NULL COMMENT '分项评分明细(JSON:创新性/可行性/团队/应用价值)',
  `review_comment` varchar(1000) DEFAULT NULL COMMENT '评审意见',
  `review_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '审核时间',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `is_deleted` tinyint NOT NULL DEFAULT '0' COMMENT '软删除标记',
  PRIMARY KEY (`id`),
  KEY `idx_project` (`project_id`),
  KEY `idx_reviewer` (`reviewer_id`),
  KEY `idx_stage` (`review_stage`),
  KEY `idx_project_stage` (`project_id`,`review_stage`),
  CONSTRAINT `fk_review_project` FOREIGN KEY (`project_id`) REFERENCES `proj_project` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `fk_review_reviewer` FOREIGN KEY (`reviewer_id`) REFERENCES `sys_user` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=1 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='项目审核记录表';

-- proj_budget
CREATE TABLE `proj_budget` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '记录ID',
  `project_id` bigint NOT NULL COMMENT '项目ID',
  `budget_item` varchar(128) NOT NULL COMMENT '预算科目',
  `budget_amount` decimal(12,2) NOT NULL DEFAULT '0.00' COMMENT '预算金额',
  `used_amount` decimal(12,2) NOT NULL DEFAULT '0.00' COMMENT '已使用金额',
  `remark` varchar(255) DEFAULT NULL COMMENT '备注说明',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `is_deleted` tinyint NOT NULL DEFAULT '0' COMMENT '软删除标记',
  PRIMARY KEY (`id`),
  KEY `idx_project` (`project_id`),
  KEY `idx_project_budget_item` (`project_id`,`budget_item`),
  CONSTRAINT `fk_budget_project` FOREIGN KEY (`project_id`) REFERENCES `proj_project` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=1 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='项目预算表';

-- proj_expense
CREATE TABLE `proj_expense` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '报销单ID',
  `expense_no` varchar(64) NOT NULL COMMENT '报销单号',
  `project_id` bigint NOT NULL COMMENT '项目ID',
  `applicant_id` bigint NOT NULL COMMENT '申请人ID',
  `applicant_name` varchar(64) NOT NULL COMMENT '申请人姓名(冗余)',
  `expense_amount` decimal(12,2) NOT NULL COMMENT '报销金额',
  `budget_item_id` bigint DEFAULT NULL COMMENT '对应预算科目ID',
  `expense_desc` varchar(500) NOT NULL COMMENT '费用说明',
  `invoice_no` varchar(128) DEFAULT NULL COMMENT '发票号码',
  `status` tinyint NOT NULL DEFAULT '0' COMMENT '审批状态: 0-草稿 1-待导师审批 2-导师审批通过 3-待学院审批 4-学院审批通过 5-待财务审批 6-已完成 7-已驳回',
  `reject_reason` varchar(500) DEFAULT NULL COMMENT '驳回原因',
  `submit_time` datetime DEFAULT NULL COMMENT '提交时间',
  `approval_time` datetime DEFAULT NULL COMMENT '最终审批时间',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `is_deleted` tinyint NOT NULL DEFAULT '0' COMMENT '软删除标记',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_expense_no` (`expense_no`),
  KEY `idx_project` (`project_id`),
  KEY `idx_applicant` (`applicant_id`),
  KEY `idx_status` (`status`),
  KEY `idx_created_at` (`created_at`),
  KEY `idx_budget_item` (`budget_item_id`),
  CONSTRAINT `fk_expense_applicant` FOREIGN KEY (`applicant_id`) REFERENCES `sys_user` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `fk_expense_budget_item` FOREIGN KEY (`budget_item_id`) REFERENCES `proj_budget` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `fk_expense_project` FOREIGN KEY (`project_id`) REFERENCES `proj_project` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=1 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='经费报销申请表';

-- proj_achievement
CREATE TABLE `proj_achievement` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '成果ID',
  `project_id` bigint NOT NULL COMMENT '项目ID',
  `achievement_type` tinyint NOT NULL COMMENT '成果类型: 1-论文 2-专利 3-软件著作权 4-竞赛获奖 5-创业成果 6-其他',
  `title` varchar(255) NOT NULL COMMENT '成果标题/名称',
  `author` varchar(255) DEFAULT NULL COMMENT '作者/发明人',
  `publish_date` date DEFAULT NULL COMMENT '发表/授权日期',
  `publisher` varchar(255) DEFAULT NULL COMMENT '发表刊物/授权机构',
  `achievement_no` varchar(128) DEFAULT NULL COMMENT '编号(专利号/登记号等)',
  `level` tinyint DEFAULT NULL COMMENT '级别: 1-校级 2-省级 3-国家级 4-国际级',
  `award_level` varchar(64) DEFAULT NULL COMMENT '获奖等级',
  `summary` text COMMENT '成果简介',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `is_deleted` tinyint NOT NULL DEFAULT '0' COMMENT '软删除标记',
  PRIMARY KEY (`id`),
  KEY `idx_project` (`project_id`),
  KEY `idx_type` (`achievement_type`),
  KEY `idx_achievement_no` (`achievement_no`),
  CONSTRAINT `fk_achievement_project` FOREIGN KEY (`project_id`) REFERENCES `proj_project` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=1 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='项目成果表';

-- proj_midterm_check
CREATE TABLE `proj_midterm_check` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '记录ID',
  `project_id` bigint NOT NULL COMMENT '项目ID',
  `progress_desc` text COMMENT '当前进展描述',
  `completed_tasks` text COMMENT '已完成任务',
  `remaining_tasks` text COMMENT '剩余任务计划',
  `problems` text COMMENT '存在问题',
  `next_plan` text COMMENT '下一步计划',
  `report` text COMMENT '中期报告',
  `budget_usage` decimal(12,2) DEFAULT NULL COMMENT '已使用经费',
  `status` tinyint NOT NULL DEFAULT '0' COMMENT '状态: 0-草稿 1-待审核 2-审核通过 3-需修改 4-已驳回',
  `reviewer_id` bigint DEFAULT NULL COMMENT '审核人ID',
  `review_comment` varchar(1000) DEFAULT NULL COMMENT '审核意见',
  `review_time` datetime DEFAULT NULL COMMENT '审核时间',
  `submit_time` datetime DEFAULT NULL COMMENT '提交时间',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `is_deleted` tinyint NOT NULL DEFAULT '0' COMMENT '软删除标记',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_project` (`project_id`),
  KEY `idx_status` (`status`),
  KEY `fk_midterm_reviewer` (`reviewer_id`),
  CONSTRAINT `fk_midterm_project` FOREIGN KEY (`project_id`) REFERENCES `proj_project` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `fk_midterm_reviewer` FOREIGN KEY (`reviewer_id`) REFERENCES `sys_user` (`id`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=1 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='项目中期检查表';

-- proj_change_request
CREATE TABLE `proj_change_request` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '申请ID',
  `project_id` bigint NOT NULL COMMENT '项目ID',
  `change_type` tinyint NOT NULL COMMENT '变更类型: 1-延期 2-人员变更 3-内容变更 4-预算调整 5-其他',
  `change_reason` varchar(1000) NOT NULL COMMENT '变更原因',
  `original_content` text COMMENT '原内容',
  `new_content` text COMMENT '变更后内容',
  `applicant_id` bigint NOT NULL COMMENT '申请人ID',
  `status` tinyint NOT NULL DEFAULT '0' COMMENT '状态: 0-待审核 1-导师同意 2-学院同意 3-校级同意 4-已驳回',
  `reject_reason` varchar(500) DEFAULT NULL COMMENT '驳回原因',
  `submit_time` datetime DEFAULT NULL COMMENT '提交时间',
  `approval_time` datetime DEFAULT NULL COMMENT '审批时间',
  `project_status_at_submit` tinyint DEFAULT NULL COMMENT '提交时项目所处状态(用于每阶段限1次配额)',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `is_deleted` tinyint NOT NULL DEFAULT '0' COMMENT '软删除标记',
  PRIMARY KEY (`id`),
  KEY `idx_project` (`project_id`),
  KEY `idx_type_status` (`change_type`,`status`),
  KEY `idx_applicant` (`applicant_id`),
  CONSTRAINT `fk_change_applicant` FOREIGN KEY (`applicant_id`) REFERENCES `sys_user` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `fk_change_project` FOREIGN KEY (`project_id`) REFERENCES `proj_project` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=1 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='项目变更/延期申请表';

-- sys_attachment
CREATE TABLE `sys_attachment` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '附件ID',
  `biz_type` varchar(64) NOT NULL COMMENT '业务类型: project-项目材料 expense-报销附件 achievement-成果材料 review-评审材料',
  `biz_id` bigint NOT NULL COMMENT '业务记录ID',
  `file_name` varchar(255) NOT NULL COMMENT '原始文件名',
  `file_path` varchar(500) NOT NULL COMMENT '存储路径',
  `file_size` bigint NOT NULL COMMENT '文件大小(字节)',
  `file_type` varchar(255) DEFAULT NULL COMMENT '文件MIME类型',
  `file_ext` varchar(16) DEFAULT NULL COMMENT '文件扩展名',
  `uploader_id` bigint NOT NULL COMMENT '上传人ID',
  `uploader_name` varchar(64) NOT NULL COMMENT '上传人姓名(冗余)',
  `download_count` int NOT NULL DEFAULT '0' COMMENT '下载次数',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '上传时间',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `is_deleted` tinyint NOT NULL DEFAULT '0' COMMENT '软删除标记',
  PRIMARY KEY (`id`),
  KEY `idx_biz` (`biz_type`,`biz_id`),
  KEY `idx_uploader` (`uploader_id`),
  CONSTRAINT `fk_attachment_uploader` FOREIGN KEY (`uploader_id`) REFERENCES `sys_user` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=1 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='附件文件表';

-- sys_operation_log
CREATE TABLE `sys_operation_log` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '日志ID',
  `user_id` bigint DEFAULT NULL COMMENT '操作用户ID',
  `username` varchar(64) DEFAULT NULL COMMENT '操作账号',
  `real_name` varchar(64) DEFAULT NULL COMMENT '操作人姓名',
  `user_role` tinyint DEFAULT NULL COMMENT '用户角色',
  `operation_type` varchar(64) NOT NULL COMMENT '操作类型: create/update/delete/login/export/approve等',
  `module_name` varchar(64) NOT NULL COMMENT '模块名称',
  `operation_desc` varchar(500) DEFAULT NULL COMMENT '操作描述',
  `request_method` varchar(16) DEFAULT NULL COMMENT '请求方法',
  `request_url` varchar(500) DEFAULT NULL COMMENT '请求URL',
  `request_params` text COMMENT '请求参数(JSON)',
  `response_code` int DEFAULT NULL COMMENT '响应状态码',
  `ip_address` varchar(64) DEFAULT NULL COMMENT '操作IP',
  `user_agent` varchar(500) DEFAULT NULL COMMENT '客户端UA',
  `cost_time` int DEFAULT NULL COMMENT '耗时(毫秒)',
  `operation_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '操作时间',
  PRIMARY KEY (`id`),
  KEY `idx_user` (`user_id`),
  KEY `idx_operation` (`operation_type`,`module_name`),
  KEY `idx_time` (`operation_time`),
  KEY `idx_username` (`username`),
  CONSTRAINT `fk_log_user` FOREIGN KEY (`user_id`) REFERENCES `sys_user` (`id`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=1 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='操作日志审计表';

SET FOREIGN_KEY_CHECKS = 1;

